2|/**
3| * export.js — multi-platform publisher (rules #3, #6, #7, #9, #12).
4| *
5| * For each approved clip in data/clips.json:
6| *   1. Burns timed subtitles once per target platform (safe-zone aware) into
7| *      Outputs/NN_slug_<platform>.mp4 (rule #3 + #7).
8| *   2. Optionally appends a branded CTA end-card (rule #6).
9| *   3. Writes data/titles.md with N A/B hook-title variants per clip (rule #9).
10| *   4. Records per-clip success in data/run_manifest.json so partial batches can
11| *      be resumed without re-doing finished clips (rule #12).
12| *
13| * A canonical, no-suffix Outputs/NN_slug.mp4 (the default platform) is always
14| * produced for backward compatibility.
15| *
16| * USAGE:
17| *   node scripts/export.js   [--platforms shorts,tiktok,reels]
18| *                             [--skip-endcard] [--skip-manifest] [--build-outputs-dir]
19| * SECURITY: all paths validated; only allowlisted commands (uv/python/ffmpeg).
20| */
21|const fs = require('fs');
22|const path = require('path');
23|const { spawnSync } = require('child_process');
24|const { loadConfig, getConfig, getPaths, getPath, validatePath } = require('./config.js');
25|
26|loadConfig();
27|const paths = getPaths();
28|const config = getConfig();
29|const ROOT_DIR = path.join(__dirname, '..');
30|
31|const CLIPS_JSON = path.join(ROOT_DIR, 'data', 'clips.json');
32|const MANIFEST_PATH = getConfig().export?.manifestFile
33|  ? path.join(ROOT_DIR, getConfig().export.manifestFile)
34|  : path.join(ROOT_DIR, 'data', 'run_manifest.json');
35|const TITLES_PATH = getConfig().export?.titlesFile
36|  ? path.join(ROOT_DIR, getConfig().export.titlesFile)
37|  : path.join(ROOT_DIR, 'data', 'titles.md');
38|
39|const DEFAULT_PLATFORM = 'shorts';
40|const ALLOWED = ['uv', 'python', 'python3', 'ffmpeg', 'ffprobe', 'node'];
41|
42|function run(cmd, args, label, timeoutMs) {
43|  if (!ALLOWED.includes(path.basename(cmd).replace(/\.exe$/i, ''))) {
44|    throw new Error(`Command not allowed: ${cmd}`);
45|  }
46|  const r = spawnSync(cmd, args, { cwd: ROOT_DIR, stdio: 'inherit', timeout: timeoutMs || 300000 });
47|  if (r.error) throw new Error(`${label} failed to start: ${r.error.message}`);
48|  if (r.status !== 0) throw new Error(`${label} exited code ${r.status}`);
49|}
50|
51|function readClips() {
52|  validatePath(CLIPS_JSON, [paths.data]);
53|  const data = JSON.parse(fs.readFileSync(CLIPS_JSON, 'utf8'));
54|  validateClips(data.clips);
55|  return data.clips;
56|}
57|
58|function validateClips(clips) {
59|  if (!Array.isArray(clips) || clips.length === 0) throw new Error('clips.json empty');
60|  for (const c of clips) {
61|    if (!c.title || !c.hook) throw new Error('Every clip needs title + hook');
62|    if (typeof c.start !== 'number' || typeof c.end !== 'number' || c.end <= c.start) {
63|      throw new Error(`Clip "${c.title}" has invalid times`);
64|    }
65|  }
66|}
67|
68|// Rule #9 — A/B hook-title variants. Cheap template expansions of the LLM title
69|// + hook into 3 variations for testing different intros.
70|function titleVariants(title, hook) {
71|  const t = String(title || '');
72|  const h = String(hook || '');
73|  const variants = [];
74|  variants.push(`The secret: ${t}`);
75|  if (h) { variants.push(`"${h}"`); if (variants.length < 3) variants.push(h.slice(0, 80)); }
76|  while (variants.length < 3) variants.push(t + ` (watch this)`);
77|  // Dedup + trim to 100 chars
78|  const out = [];
79|  for (const v of variants) {
80|    const clean = v.replace(/\s+/g, ' ').trim().slice(0, 100);
81|    if (clean && !out.includes(clean)) out.push(clean);
82|    if (out.length === 3) break;
83|  }
84|  return out;
85|}
86|
87|function writeTitlesMd(clips) {
88|  const lines = ['# Hook / Title A/B Set', '', `Generated: ${new Date().toISOString()}`, ''];
89|  clips.forEach((c, idx) => {
90|    const num = String(idx + 1).padStart(2, '0');
91|    lines.push(`## Clip ${num} — ${c.title}`);
92|    lines.push(`- **Title:** ${c.title}`);
93|    lines.push(`- **Hook (first 3s):** ${c.hook}`);
94|    titleVariants(c.title, c.hook).forEach((v, k) => lines.push(`- **Variant ${k + 1}:** ${v}`));
95|    lines.push('');
96|  });
97|  fs.writeFileSync(TITLES_PATH, lines.join('\n'));
98|  console.log(`[export] titles + hooks -> ${TITLES_PATH}`);
99|}
100|
101|function writeManifest(entries) {
102|  const m = { updatedAt: new Date().toISOString(), entries };
103|  fs.mkdirSync(path.dirname(MANIFEST_PATH), { recursive: true });
104|  fs.writeFileSync(MANIFEST_PATH, JSON.stringify(m, null, 2));
105|}
106|
107|function loadManifest() {
108|  if (!fs.existsSync(MANIFEST_PATH)) return { updatedAt: null, entries: {} };
109|  try {
110|    const raw = JSON.parse(fs.readFileSync(MANIFEST_PATH, 'utf8'));
111|    // Normalize: export.js persists resume state under `entries`; extract.js
112|    // writes the same file with a `clips[]` shape (cut audit). Treat a foreign
113|    // schema as no export-resume state instead of crashing on entries[...].
114|    if (!raw || typeof raw !== 'object') return { updatedAt: null, entries: {} };
115|    return { updatedAt: raw.updatedAt || null, entries: raw.entries || {} };
116|  } catch { return { updatedAt: null, entries: {} }; }
117|}
118|
119|function slug(title, num) {
120|  return String(title || `clip_${num}`).toLowerCase()
121|    .replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 60);
122|}
