124|function main() {
125|  const args = process.argv.slice(2);
126|  const flags = new Set(args.filter(a => a.startsWith('--')));
127|  let platforms;
128|  const pIdx = args.indexOf('--platforms');
129|  platforms = (pIdx !== -1 && args[pIdx + 1])
130|    ? args[pIdx + 1].split(',').map(s => s.trim()).filter(Boolean)
131|    : (config.subtitleConfig?.platforms || [DEFAULT_PLATFORM]);
132|
